/*
 * A142946  Primes congruent to 47 mod 64.
 * https://oeis.org/A142946
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the n-th prime p with p % 64 == 47 (generated by
 *            incremental trial division)
 * Range:     u8 n <= 2, u16 n <= 209, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_small
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime_small.h"

/* Dynamic array of primes congruent to 47 (mod 64) */
static seq_t *primes = NULL;
static size_t  prime_cnt   = 0;   /* number of primes stored */
static size_t  prime_cap   = 0;   /* allocated capacity       */

/* Next candidate value (always ≡ 47 (mod 64)) */
static uint64_t next_candidate = 47;

/* Grow the primes array when needed */
static void grow_primes(void)
{
    size_t new_cap = prime_cap ? prime_cap << 1 : 64;
    seq_t *tmp = (seq_t *)realloc(primes, new_cap * sizeof(seq_t));
    if (!tmp && new_cap) abort();          /* allocation failure  */
    primes = tmp;
    prime_cap = new_cap;
}

/* Generate the next prime congruent to 47 mod 64 and store it */
static void generate_next_prime(void)
{
    while (true) {
        if (is_prime_small(next_candidate)) {
            if (prime_cnt == prime_cap) grow_primes();
            primes[prime_cnt++] = (seq_t)next_candidate;
            next_candidate += 64;
            break;
        }
        next_candidate += 64;
    }
}

/* Return the n-th prime ≡ 47 (mod 64) */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                          /* undefined for n = 0 */
    /* Ensure we have at least n stored primes */
    while (prime_cnt < n) generate_next_prime();
    return primes[n - 1];
}
